from collections import deque

# Build adjacency list
adj = {}
for edge in edges:
    parts = edge.split(' -> ')
    src, dst = parts[0], parts[1]
    if src not in adj:
        adj[src] = []
    adj[src].append(dst)

# Find the starting node
start_node = "872488f88d"
print(f"Start node: {start_node}")
print(f"Start node in adj: {start_node in adj}")

# BFS to find nodes at exactly depth 4
def bfs_depth_k(adj, start, k):
    if start not in adj:
        return []

    # (node, depth)
    queue = deque()
    # Start with neighbors at depth 1
    for neighbor in adj.get(start, []):
        queue.append((neighbor, 1))

    visited_at_depth = {start: 0}
    nodes_at_depth_k = []

    while queue:
        node, depth = queue.popleft()

        # Skip if we've already seen this node at a shallower depth
        if node in visited_at_depth:
            continue
        visited_at_depth[node] = depth

        if depth == k:
            nodes_at_depth_k.append(node)
        elif depth < k:
            # Continue BFS
            for neighbor in adj.get(node, []):
                if neighbor not in visited_at_depth:
                    queue.append((neighbor, depth + 1))

    return nodes_at_depth_k

result = bfs_depth_k(adj, start_node, 4)
print(f"Nodes at depth 4: {result}")
print(f"Count: {len(result)}")
